    ringCv = document.getElementById('ring');   ringCtx  = G2Scaler.prepare(ringCv, 320, 200);
    shoutCv = document.getElementById('shout'); shoutCtx = G2Scaler.prepare(shoutCv, 320, 200);
    ringShade = document.getElementById('ringShade');
    fxCv   = document.getElementById('fx');     fxCtx    = G2Scaler.prepare(fxCv, 320, 200);

    /* 할일 19 — 링 아이콘 **그림**은 원본 `.ICO` 직독입니다. */
    G2Ring.useNativeIcons(true);
    G2Ring.load('자산/', function (e) { if (e) fail('ring 자산: ' + e.message); });
    G2Hud.init(document.getElementById('hud'), battle, {
      base: '자산/', onReady: function (e) { if (e) fail('HUD 자산: ' + e.message); }
    });
    /* 원본 글꼴은 게임 폴더에서 그대로 읽습니다 — 서버가 /원본/ 으로 내줍니다. */
